import { getJson } from '../../api/http';

/** The sheet's audit lines exactly as the audit file holds them, newest first; with a name (case and
 *  surrounding spaces ignored; blank: all), only those carrying name=<it> or person=<it>, then those of the sheet's
 *  descendants (each sheet's newest first, sheets by id), followed, when that
 *  person was transferred here, by the lines about them from the sheet they came from, newest first. */
export function listAudit(sheetId: string, name: string): Promise<string[]> {
  return getJson<string[]>(`/api/sheets/${encodeURIComponent(sheetId)}/audit?name=${encodeURIComponent(name)}`);
}
import { SheetBody } from '../../slots/defs/sheetBody';
import { AuditViewer } from './AuditViewer';

export const contributions = [
  SheetBody.fill({ order: 90, Component: AuditViewer }),
];
import { useState } from 'react';
import { useMutation } from '@tanstack/react-query';
import { listAudit } from './api';

/** The sheet's audit file, read on demand: every line (newest first), or with a name only those about
 *  that person. It shows what the file holds; it keeps nothing of its own. */
export function AuditViewer({ sheetId }: { sheetId: string; user: string }) {
  const [filter, setFilter] = useState('');
  const show = useMutation({ mutationFn: (name: string) => listAudit(sheetId, name) });

  return (
    <section>
      <h3>Audit</h3>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          show.reset();
          show.mutate(filter);
        }}
      >
        <input data-testid="audit-filter" placeholder="Name (blank: all)" value={filter}
          onChange={(e) => setFilter(e.target.value)} />{' '}
        <button type="submit" data-testid="audit-show" disabled={show.isPending}>
          Show
        </button>
        {show.isError && <span data-testid="audit-error">The audit could not be read.</span>}
      </form>
      <ul>
        {(show.data ?? []).map((line, i) => (
          <li key={i} data-testid="audit-line">{line}</li>
        ))}
      </ul>
    </section>
  );
}
